21: /**
22:  * Validates that a URL is safe to open in a browser.
23:  * Only allows HTTP and HTTPS URLs to prevent command injection.
24:  *
25:  * @param url The URL to validate
26:  * @throws Error if the URL is invalid or uses an unsafe protocol
27:  */
28: function validateUrl(url: string): void {
29:   let parsedUrl: URL;
30: 
31:   try {
32:     parsedUrl = new URL(url);
33:   } catch {
34:     throw new Error('Invalid URL');
35:   }
36: 
37:   // Only allow HTTP and HTTPS protocols
38:   if (parsedUrl.protocol !== 'http:' && parsedUrl.protocol !== 'https:') {
39:     throw new Error(
40:       `Unsafe protocol: ${parsedUrl.protocol}. Only HTTP and HTTPS are allowed.`,
41:     );
42:   }
43: 
44:   // Additional validation: ensure no newlines or control characters
45:   if (/[\r\n\x00-\x1F]/.test(url)) {
46:     throw new Error('URL contains invalid characters');
47:   }
48: }
49: 
50: /**
51:  * Opens a URL in the default browser using platform-specific commands.
52:  * This implementation avoids shell injection vulnerabilities by:
53:  * 1. Validating the URL to ensure it's HTTP/HTTPS only
54:  * 2. Using execFile instead of exec to avoid shell interpretation
55:  * 3. Passing the URL as an argument rather than constructing a command string
56:  *
57:  * @param url The URL to open
58:  * @param execFileFn The function to execute a command. Defaults to node's execFile.
59:  * @throws Error if the URL is invalid or if opening the browser fails
60:  */
61: export async function openBrowserSecurely(
62:   url: string,
63:   execFileFn: typeof execFile = execFile,
64: ): Promise<void> {
65:   // Validate the URL first
66:   validateUrl(url);
67: 
68:   const platformName = platform();
69:   let command: string;
70:   let args: string[];
71: 
72:   switch (platformName) {
73:     case 'darwin':
74:       // macOS
75:       command = 'open';
76:       args = [url];
77:       break;
78: 
79:     case 'win32':
80:       // Windows - use PowerShell with Start-Process
81:       // This avoids the cmd.exe shell which is vulnerable to injection
82:       command = 'powershell.exe';
83:       args = [
84:         '-NoProfile',
85:         '-NonInteractive',
86:         '-WindowStyle',
87:         'Hidden',
88:         '-Command',
89:         `Start-Process '${url.replace(/'/g, "''")}'`,
90:       ];
91:       break;
92: 
93:     case 'linux':
94:     case 'freebsd':
95:     case 'openbsd':
96:       // Linux and BSD variants
97:       // Try xdg-open first, fall back to other options
98:       command = 'xdg-open';
99:       args = [url];
100:       break;
101: 
102:     default:
103:       throw new Error(`Unsupported platform: ${platformName}`);
104:   }
105: 
106:   const options: Record<string, unknown> = {
107:     // Don't inherit parent's environment to avoid potential issues
108:     env: {
109:       ...process.env,
110:       // Ensure we're not in a shell that might interpret special characters
111:       SHELL: undefined,
112:     },
113:     // Detach the browser process so it doesn't block
114:     detached: true,
115:     stdio: 'ignore',
116:   };
117: 
