128:             reject(error);
129:           }
130:         },
131:       );
132: 
133:       // The 'error' event is critical. It fires if the command cannot be found or spawned.
134:       child.on('error', (error) => {
135:         reject(error);
136:       });
137: 
138:       // If the process spawns successfully, 'xdg-open' and similar commands
139:       // exit almost immediately. We don't need to wait for the browser to close.
140:       // We can consider the job done if the process exits with code 0.
141:       child.on('exit', (code) => {
142:         if (code === 0) {
143:           resolve();
144:         } else {
145:           reject(new Error(`Process exited with code ${code}`));
146:         }
147:       });
148:     });
149:   };
