21:    */
22:   static async loadCredentials(): Promise<Credentials | null> {
23:     try {
24:       const credentials = await this.storage.getCredentials(MAIN_ACCOUNT_KEY);
25: 
26:       if (credentials?.token) {
27:         const { accessToken, refreshToken, expiresAt, tokenType, scope } =
28:           credentials.token;
29:         // Convert from OAuthCredentials format to Google Credentials format
30:         const googleCreds: Credentials = {
31:           access_token: accessToken,
32:           refresh_token: refreshToken || undefined,
33:           token_type: tokenType || undefined,
34:           scope: scope || undefined,
35:         };
36: 
37:         if (expiresAt) {
38:           googleCreds.expiry_date = expiresAt;
39:         }
40: 
41:         return googleCreds;
42:       }
