50:   /**
51:    * Save OAuth credentials
52:    */
53:   static async saveCredentials(credentials: Credentials): Promise<void> {
54:     // Convert Google Credentials to OAuthCredentials format
55:     const mcpCredentials: OAuthCredentials = {
56:       serverName: MAIN_ACCOUNT_KEY,
57:       token: {
58:         accessToken: credentials.access_token || undefined,
59:         refreshToken: credentials.refresh_token || undefined,
60:         tokenType: credentials.token_type || 'Bearer',
61:         scope: credentials.scope || undefined,
62:         expiresAt: credentials.expiry_date || undefined,
63:       },
64:       updatedAt: Date.now(),
65:     };
