710:   private extractAttachmentsAndBody(
711:     payload: gmail_v1.Schema$MessagePart,
712:     result: { body: string; attachments: GmailAttachment[] } = {
713:       body: '',
714:       attachments: [],
715:     },
716:   ) {
717:     if (!payload) return result;
718: 
719:     // Handle body parts
720:     if (payload.body?.data) {
721:       // If it's the main body (and not an attachment)
722:       if (!payload.filename || !payload.body.attachmentId) {
723:         if (payload.mimeType?.startsWith('text/')) {
724:           // Prioritize plain text over HTML for direct body extraction
725:           if (!result.body || payload.mimeType === 'text/plain') {
726:             result.body = Buffer.from(payload.body.data, 'base64').toString(
727:               'utf-8',
728:             );
729:           }
730:         }
731:       }
732:     }
