343: 
344:       const tabs = this._flattenTabs(res.data.tabs || []);
345: 
346:       // If tabId is provided, try to find it
347:       if (tabId) {
348:         const tab = tabs.find((t) => t.tabProperties?.tabId === tabId);
349:         if (!tab) {
350:           throw new Error(`Tab with ID ${tabId} not found.`);
351:         }
352: 
353:         const content = tab.documentTab?.body?.content;
354:         if (!content) {
355:           return {
356:             content: [
357:               {
358:                 type: 'text' as const,
359:                 text: '',
360:               },
361:             ],
362:           };
363:         }
364: 
365:         let text = '';
366:         content.forEach((element) => {
367:           text += this._readStructuralElement(element);
368:         });
369: 
370:         return {
371:           content: [
372:             {
373:               type: 'text' as const,
