375:             },
376:           ],
377:         };
378:       }
379: 
380:       // If no tabId provided
381:       if (tabs.length === 0) {
382:         return {
383:           content: [
384:             {
385:               type: 'text' as const,
386:               text: '',
387:             },
388:           ],
389:         };
390:       }
391: 
392:       // If only 1 tab, return plain text (backward compatibility)
393:       if (tabs.length === 1) {
394:         const tab = tabs[0];
395:         let text = '';
396:         if (tab.documentTab?.body?.content) {
397:           tab.documentTab.body.content.forEach((element) => {
398:             text += this._readStructuralElement(element);
399:           });
400:         }
401:         return {
402:           content: [
403:             {
404:               type: 'text' as const,
405:               text: text,
406:             },
407:           ],
408:         };
409:       }
410: 
411:       // If multiple tabs, return JSON
412:       const tabsData = tabs.map((tab, index) => {
413:         let tabText = '';
414:         if (tab.documentTab?.body?.content) {
415:           tab.documentTab.body.content.forEach((element) => {
416:             tabText += this._readStructuralElement(element);
417:           });
418:         }
419:         return {
420:           tabId: tab.tabProperties?.tabId,
